var i=`0194-zabaglione`;var t=`world-0194`;var n=`IT`;var r=`southern-europe`;var s=4;var g=21;var o={en:`Zabaglione`,ua:`Дзабайоне`};var l={en:`A classic dish from Italy, featuring egg yolk, raspberry, white granulated sugar, marsala wine. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: яєчний жовток, малина, білий цукор-пісок, вино марсала. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Whisk egg yolks and sugar in a heatproof bowl until pale and thick.`,ua:`Збийте жовтки з цукром у жаростійкій мисці до світлої густої маси.`,t:[`whipping`],m:8,i:[[`egg-yolk`,6,`pcs`],[`white-granulated-sugar`,110,`g`]]},{en:`Place the bowl over a pan of barely simmering water; whisk in Marsala continuously until the custard is airy and thick, cooking the egg mixture thoroughly.`,ua:`Поставте миску над ледь киплячою водою; постійно збиваючи, введіть марсалу й готуйте до пишного густого крему, добре прогрівши яєчну масу.`,t:[`hot-water-bath`,`whisking`],m:10,i:[[`marsala-wine`,170,`ml`]]},{en:`Serve the warm zabaglione immediately with the berries.`,ua:`Подавайте тепле дзабайоне одразу, доповнивши ягодами.`,t:[`seasoning`,`garnishing`],m:3,i:[[`raspberry`,180,`g`]]}];var u={slug:i,id:t,country:`IT`,region:r,servings:4,minutes:21,title:o,text:l,steps:h};export{n as country,u as default,t as id,g as minutes,r as region,s as servings,i as slug,h as steps,l as text,o as title};